-- ═══════════════════════════════════════════════════════════════════
--  КАНИКУЛЫ С ONE! — НАСТРОЙКА SUPABASE
--  Файл для запуска в Supabase Dashboard → SQL Editor → Run.
--
--  Создаёт и наполняет 4 таблицы контента:
--    content_shifts            — 10 смен (теги и направления с миссиями в JSONB)
--    content_competencies      — 12 компетенций (иконки и цвета)
--    content_badge_definitions — значки «старт»/«мастер» для каждого направления каждой смены
--    content_disc_config       — настройки DISC: colors, skill_map, combo
--
--  Скрипт можно запускать повторно: таблицы пересоздаются.
-- ═══════════════════════════════════════════════════════════════════

DROP TABLE IF EXISTS public.content_badge_definitions CASCADE;
DROP TABLE IF EXISTS public.content_disc_config CASCADE;
DROP TABLE IF EXISTS public.content_competencies CASCADE;
DROP TABLE IF EXISTS public.content_shifts CASCADE;

-- ────────────────────────────────────────────────────────────
-- 1. Таблица content_shifts — концепции смен
-- ────────────────────────────────────────────────────────────
CREATE TABLE public.content_shifts (
  shift_id     INT UNIQUE,
  currency     TEXT,
  title        TEXT,
  subtitle     TEXT,
  tags         JSONB,
  legend       TEXT,
  gamification TEXT,
  english      TEXT,
  sport        TEXT,
  skills       TEXT,
  product      TEXT,
  directions   JSONB,
  created_at   TIMESTAMPTZ DEFAULT now()
);


-- ────────────────────────────────────────────────────────────
-- 2. Таблица content_competencies — 12 компетенций
-- ────────────────────────────────────────────────────────────
CREATE TABLE public.content_competencies (
  comp_id    TEXT UNIQUE,
  name       TEXT,
  icon       TEXT,
  color      TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);


-- ────────────────────────────────────────────────────────────
-- 3. Таблица content_badge_definitions — значки направлений
--    Для каждого направления каждой смены:
--    • «старт»  — за первую миссию  (rarity: common)
--    • «мастер» — за последнюю миссию (rarity: rare)
-- ────────────────────────────────────────────────────────────
CREATE TABLE public.content_badge_definitions (
  badge_id       TEXT UNIQUE,
  name           TEXT,
  icon           TEXT,
  shift_id       INT,
  direction_name TEXT,
  mission_name   TEXT,
  "condition"    TEXT,
  rarity         TEXT,
  "desc"         TEXT,
  created_at     TIMESTAMPTZ DEFAULT now()
);


-- ────────────────────────────────────────────────────────────
-- 4. Таблица content_disc_config — конфигурация DISC
-- ────────────────────────────────────────────────────────────
CREATE TABLE public.content_disc_config (
  config_key   TEXT UNIQUE,
  config_value JSONB,
  created_at   TIMESTAMPTZ DEFAULT now()
);


-- ═══════════════════════════════════════════════════════════════════
-- 5. Таблица participations — участие в миссиях (студент + миссия + команда 1..10)
--    Один участник может быть в нескольких миссиях; не все участвуют во всех.
-- ═══════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.participations (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id  UUID REFERENCES public.students(id) ON DELETE CASCADE,
  shift_id    INT  NOT NULL,
  squad       INT  NOT NULL CHECK (squad BETWEEN 1 AND 10),
  created_at  TIMESTAMPTZ DEFAULT now(),
  UNIQUE (student_id, shift_id)
);
ALTER TABLE public.participations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "anon_all_participations"
  ON public.participations FOR ALL USING (true);
CREATE POLICY "anon_read_participations"
  ON public.participations FOR SELECT USING (true);

SELECT id, shift, squad FROM public.students s
WHERE s.shift IS NOT NULL AND s.squad IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM public.participations p
                  WHERE p.student_id = s.id AND p.shift_id = s.shift)
ON CONFLICT (student_id, shift_id) DO NOTHING;

-- ═══════════════════════════════════════════════════════════════════
-- 6. Таблица cards — коллекция карточек (84 шт.)
-- ═══════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.cards (
  id           BIGSERIAL PRIMARY KEY,
  num          INT  NOT NULL UNIQUE,
  section      TEXT NOT NULL CHECK (section IN ('inventory','relic','badge','boss','shop','mystery')),
  icon         TEXT NOT NULL,
  name         TEXT NOT NULL,
  rarity       TEXT NOT NULL DEFAULT 'Обычный',
  bonus        TEXT,
  mission      INT,
  shift        INT,
  week         INT,
  hp           INT,
  reward       TEXT,
  price        TEXT,
  item_type    TEXT,
  condition    TEXT,
  chance       TEXT,
  value_type   TEXT,
  value        TEXT,
  created_at   TIMESTAMPTZ DEFAULT now()
);
ALTER TABLE public.cards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "anon_all_cards"
  ON public.cards FOR ALL USING (true);
CREATE POLICY "anon_read_cards"
  ON public.cards FOR SELECT USING (true);







