INSERT INTO public.content_shifts (shift_id, currency, title, subtitle, tags, legend, gamification, english, sport, skills, product, directions) VALUES
(1, 'Нейро-коины', '«Кибер-Атлеты: Хроники Будущего»', 'PHYGITAL & SCI-FI', '["Спорт","IT","Биотех","Предпринимательство"]'::jsonb, 'Участники — «Агенты Будущего» в секретной академии. Их задача — спасти цифровую вселенную, развивая физические и интеллектуальные способности. Каждый день — новая миссия, каждая победа — очки опыта.', 'Каждый участник получает браслет агента с личным профилем. За выполнение заданий начисляются «Нейро-коины». В финале — командная «Битва с Боссом» на английском языке.', 'Все задания, брифинги и тренировки в двуязычном режиме. Вожатые играют роль «Кураторов из будущего» и общаются с детьми на английском.', 'Нейрофитнес и упражнения на реакцию (Blazepod), балансборды, лазертаг, стрельба из лука (Archery Tag) и современный мечевой бой.', 'Инженер умных городов, AI-специалист и биохакер.', 'Собственный датчик-гаджет на micro:bit. Ребёнок сам его собирает, настраивает и в финале защищает перед командой на «Битве с Боссом».', '[{"name":"Спорт","icon":"🏅","missions":[{"name":"Нейрофитнес на Blazepod","desc":"Тренировка реакции и координации с LED-панелями","skills":["persistence","adaptability"],"professions":["Спортивный аналитик","Тренер по биохакингу"],"futureSkills":["Работа с LED-тренажёрами","Анализ физических показателей"]},{"name":"Балансборды и стабильность","desc":"Работа на нестабильных платформах для укрепления кора","skills":["persistence","self_organization"],"professions":["Тренер по функциональной подготовке","Реабилитолог"],"futureSkills":["Тренировки на нестабильных платформах","Профилактика травм"]},{"name":"Лазертаг-миссия","desc":"Командная тактическая игра в условиях «цифровой вселенной»","skills":["cooperation","problem_solving"],"professions":["Киберспортивный тренер","Оператор тактических симуляций"],"futureSkills":["Тактическое командное взаимодействие","Работа с игровыми сенсорами"]},{"name":"Archery Tag","desc":"Стрельба из лука мягкими стрелами в формате соревнования","skills":["persistence","self_organization"],"professions":["Инструктор по стрельбе","Спортсмен кибер-эпохи"],"futureSkills":["Управление стрессом в соревнованиях","Точная моторика и прицеливание"]},{"name":"Мечевой бой","desc":"Современный фехтовальный бой с безопасным инвентарём","skills":["initiative","adaptability"],"professions":["Фехтовальщик","Хореограф боевых сцен"],"futureSkills":["Современное фехтование","Чтение действий соперника"]}]},{"name":"IT","icon":"💻","missions":[{"name":"Программирование на micro:bit","desc":"Настройка сенсоров и первые шаги в коде","skills":["problem_solving","learning_ability"],"professions":["IoT-разработчик","Робо-инженер"],"futureSkills":["Программирование на Python","Работа с микроконтроллерами"]},{"name":"Сборка датчика-гаджета","desc":"Конструирование персонального устройства из компонентов","skills":["creativity","problem_solving"],"professions":["Hardware-инженер","Инженер-прототипировщик"],"futureSkills":["Сборка электроники","Проектирование устройств"]},{"name":"Основы анализа данных","desc":"Сбор данных с датчиков и визуализация результатов","skills":["critical_thinking","learning_ability"],"professions":["Data Scientist","Аналитик данных"],"futureSkills":["Визуализация данных","Работа с датасетами"]},{"name":"Эко-полис: мини-проект","desc":"Проектирование элемента умного города с 3D-моделированием","skills":["creativity","communication"],"professions":["Урбанист","UX-дизайнер умных городов"],"futureSkills":["3D-моделирование","Проектирование городских сервисов"]}]},{"name":"Биотех","icon":"🧬","missions":[{"name":"Биохакинг: пульс и反应","desc":"Измерение реакции и пульса до и после нагрузки","skills":["curiosity","critical_thinking"],"professions":["Биохакер","Специалист по спортивной медицине"],"futureSkills":["Измерение биометрических показателей","Интерпретация данных организма"]},{"name":"Анализ данных тела","desc":"Сравнение биометрических показателей участников","skills":["critical_thinking","problem_solving"],"professions":["Спортивный аналитик","Врач спортивной медицины"],"futureSkills":["Сравнительная статистика","Работа с носимыми устройствами"]},{"name":"Эко-полис: зелёные технологии","desc":"Проектирование экологичных решений для умного города","skills":["creativity","social_position"],"professions":["Инженер GreenTech","Урбанист-эколог"],"futureSkills":["Проектирование экорешений","Возобновляемая энергетика"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Нейро-коины: внутренняя валюта","desc":"Заработок и управление игровой валютой через задания","skills":["self_organization","problem_solving"],"professions":["Финансовый аналитик","Гейм-дизайнер игровых экономик"],"futureSkills":["Управление личным бюджетом","Игровая экономика"]},{"name":"Питчинг гаджета","desc":"Защита своего проекта перед «инвестиционным комитетом»","skills":["communication","initiative"],"professions":["Продакт-менеджер","Стартап-предприниматель"],"futureSkills":["Публичные питчи","Презентация продукта"]},{"name":"Юнит-экономика продукта","desc":"Расчёт стоимости и ценности созданного устройства","skills":["critical_thinking","problem_solving"],"professions":["Продуктовый аналитик","Экономист проекта"],"futureSkills":["Расчёт юнит-экономики","Ценообразование"]}]}]'::jsonb),
(2, 'Ресурсы колонии', '«Terraforming: Колонизаторы Новых Миров»', 'ADVENTURE & ECO-TECH', '["Спорт","Биотех","Дипломатия","Предпринимательство"]'::jsonb, 'Дети — участники международной экспедиции на планете «Тера-2». Их задача — построить жизнеспособную колонию: найти энергию, вырастить еду, обустроить спорт-арену и защитить базу от угроз.', 'Весь кампус превращается в карту планеты. Каждое утро — «Совет Альянса», где команды планируют день. Ресурсы (вода, энергия, кислород) зарабатываются через спорт и решение кейсов.', 'Официальный язык колонии — английский. Все чертежи, инструкции и переговоры между командами-«базами» — только на английском.', 'Школа выживания, ориентирование на местности, верёвочный курс, скалодром, «Захват флага» и детская полоса препятствий в стиле Spartan Race.', 'Сити-фермер, архитектор энергоэффективных домов и специалист по переработке.', 'Мини-гидропонная установка, презентация колонии на английском. В финале — защита проекта перед «Советом директоров Земли».', '[{"name":"Спорт","icon":"🏅","missions":[{"name":"Школа выживания","desc":"Базовые навыки ориентирования и пребывания на природе","skills":["adaptability","problem_solving"],"professions":["Инструктор по выживанию","Спасатель"],"futureSkills":["Ориентирование на местности","Безопасность в природе"]},{"name":"Верёвочный курс","desc":"Преодоление препятствий на высоте с элементами скалодрома","skills":["persistence","cooperation"],"professions":["Тренер верёвочного парка","Инструктор по активному отдыху"],"futureSkills":["Страховочные системы","Работа на высоте"]},{"name":"Захват флага","desc":"Командная тактическая игра за контроль территории","skills":["cooperation","initiative"],"professions":["Тренер командных видов спорта","Киберспортивный стратег"],"futureSkills":["Командная тактика","Стратегическое планирование"]},{"name":"Полоса препятствий Spartan","desc":"Физическое испытание на выносливость и ловкость","skills":["persistence","adaptability"],"professions":["Тренер по кроссфиту","Организатор гонок с препятствиями"],"futureSkills":["Функциональный тренинг","Развитие выносливости"]}]},{"name":"Биотех","icon":"🧬","missions":[{"name":"Гидропонная установка","desc":"Сборка мини-фермы для выращивания растений без почвы","skills":["problem_solving","learning_ability"],"professions":["Сити-фермер","Агроинженер"],"futureSkills":["Гидропоника и аэропоника","Выращивание растений без почвы"]},{"name":"Альтернативная энергетика","desc":"Проектирование источников энергии для колонии","skills":["creativity","problem_solving"],"professions":["Инженер возобновляемой энергетики","Специалист по автономным энергосистемам"],"futureSkills":["Солнечная и ветровая энергетика","Энергосбережение"]},{"name":"Переработка ресурсов","desc":"Система tái利用 отходов в замкнутом цикле","skills":["critical_thinking","social_position"],"professions":["Эко-технолог","Специалист по переработке отходов"],"futureSkills":["Замкнутые циклы производства","Сортировка и рециклинг"]}]},{"name":"Дипломатия","icon":"🤝","missions":[{"name":"Совет Альянса","desc":"Утренние совещания команд-баз для планирования дня","skills":["communication","self_organization"],"professions":["Дипломат","Фасилитатор встреч"],"futureSkills":["Проведение совещаний","Публичная дискуссия"]},{"name":"Переговоры о ресурсах","desc":"Обмен ресурсами между командами на английском","skills":["communication","critical_thinking"],"professions":["Переговорщик","Международный менеджер"],"futureSkills":["Техники переговоров на английском","Достижение win-win решений"]},{"name":"Разрешение конфликтов","desc":"Поиск компромиссов в спорных ситуациях колонии","skills":["communication","adaptability"],"professions":["Медиатор","HR-специалист"],"futureSkills":["Медиация конфликтов","Эмоциональный интеллект"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Стартап колонии","desc":"Каждая команда — стартап с распределёнными ролями","skills":["initiative","creativity"],"professions":["Основатель стартапа","Продакт-менеджер"],"futureSkills":["Распределение ролей в команде","Запуск MVP"]},{"name":"Защита перед Советом директоров","desc":"Презентация гидропонной установки жюри из взрослых","skills":["communication","social_position"],"professions":["Презентатор","Менеджер по работе с инвесторами"],"futureSkills":["Защита проектов","Питч инвесторам"]},{"name":"Бизнес-план колонии","desc":"Расчёт ресурсов и планирование развития поселения","skills":["critical_thinking","self_organization"],"professions":["Бизнес-аналитик","Планировщик проектов"],"futureSkills":["Составление бизнес-плана","Ресурсное планирование"]}]}]'::jsonb),
(3, 'Агентские баллы', '«Meta-Agency: Детективы Времени»', 'MEDIA & SOFT SKILLS', '["Медиа","Спорт","IT","Дипломатия"]'::jsonb, 'Временной континуум нарушен, и только дети-агенты «Meta-Agency» могут его восстановить. Каждый день — новое детективное дело: расшифровать код, опросить свидетелей, собрать доказательства и сделать вывод.', 'Каждое утро дети получают новое дело: шифры, измерения, интервью со «свидетелями». Все результаты фиксируются в «Цифровом портфолио Агента» — личном досье участника.', 'Язык агентства — английский. Все документы засекречены и написаны на английском. Дети общаются с «иностранными агентами» и защищают расследования на английском.', 'Капоэйра, йога и стретчинг, фехтование или современный мечевой бой, фрисби-алтимат и доджбол — каждый день разная активность.', 'Цифровой лингвист, специалист по кибербезопасности и медиапродюсер.', 'Детективный ролик или подкаст на английском с хромакеем и ИИ-монтажом. В финале — брифинг перед родителями.', '[{"name":"Медиа","icon":"🎬","missions":[{"name":"Детективный ролик","desc":"Съёмка мини-фильма-расследования на английском","skills":["creativity","communication"],"professions":["Режиссёр","Видеопродюсер"],"futureSkills":["Съёмка короткого кино","AI-монтаж видео"]},{"name":"Подкаст Агента","desc":"Запись аудио-расследования с эффектами и интервью","skills":["communication","creativity"],"professions":["Подкастер","Звукорежиссёр"],"futureSkills":["Запись и монтаж аудио","Сторителлинг в подкастах"]},{"name":"Хромакей и ИИ-монтаж","desc":"Использование зелёного экрана и ИИ для спецэффектов","skills":["creativity","learning_ability"],"professions":["VFX-художник","Моушн-дизайнер"],"futureSkills":["Работа с хромакеем","Генеративный ИИ в медиа"]},{"name":"Финальный брифинг","desc":"Презентация результатов расследования родителям","skills":["communication","social_position"],"professions":["Спикер","PR-менеджер"],"futureSkills":["Публичные выступления","Презентация расследований"]}]},{"name":"Спорт","icon":"🏅","missions":[{"name":"Капоэйра","desc":"Бразильское боевое искусство-танец для координации","skills":["adaptability","persistence"],"professions":["Тренер по капоэйре","Хореограф"],"futureSkills":["Бразильская капоэйра","Координация движений"]},{"name":"Фехтование на мягких мечах","desc":"Тактический бой с элементами фехтования","skills":["initiative","critical_thinking"],"professions":["Фехтовальщик","Тренер по фехтованию"],"futureSkills":["Тактическое фехтование","Быстрое принятие решений"]},{"name":"Фрисби-алтимат","desc":"Командная игра с летающим диском","skills":["cooperation","communication"],"professions":["Тренер по алтимат-фрисби","Организатор спортивных лиг"],"futureSkills":["Spirit of the Game","Командное взаимодействие"]},{"name":"Доджбол-турнир","desc":"Быстрая реакция и командная стратегия","skills":["adaptability","cooperation"],"professions":["Организатор спортивных турниров","Тренер по подвижным играм"],"futureSkills":["Реакция и ловкость","Турнирная организация"]}]},{"name":"IT","icon":"💻","missions":[{"name":"Расшифровка шифров","desc":"Взлом кодов и密码 с помощью логики и программирования","skills":["problem_solving","critical_thinking"],"professions":["Криптограф","Специалист по кибербезопасности"],"futureSkills":["Классическая криптография","Основы программирования"]},{"name":"Цифровое портфолио Агента","desc":"Ведение личного досье в цифровом формате","skills":["self_organization","creativity"],"professions":["UX-дизайнер","Контент-стратег"],"futureSkills":["Ведение цифрового портфолио","Дизайн личного бренда"]},{"name":"ИИ-монтаж видео","desc":"Автоматизация монтажа с помощью искусственного интеллекта","skills":["learning_ability","creativity"],"professions":["AI-монтажёр","Медиаинженер"],"futureSkills":["Нейросети для видеомонтажа","Автоматизация рутинных задач"]}]},{"name":"Дипломатия","icon":"🤝","missions":[{"name":"Интервью со свидетелями","desc":"Допрос «иностранных агентов» на английском","skills":["communication","curiosity"],"professions":["Журналист-расследователь","Детектив"],"futureSkills":["Интервьюирование на английском","Активное слушание"]},{"name":"Межагентские переговоры","desc":"Координация с другими «отделами» для раскрытия дела","skills":["cooperation","communication"],"professions":["Дипломат","Координатор проектов"],"futureSkills":["Кросс-культурная коммуникация","Координация команд"]},{"name":"Защита расследования","desc":"Публичная презентация выводов перед жюри","skills":["communication","social_position"],"professions":["Аналитик-докладчик","Юрист"],"futureSkills":["Аргументация выводов","Публичная риторика"]}]}]'::jsonb),
(4, 'Крипто-кредиты', '«Future Makers: Академия Прикладного Будущего»', 'STEM & DESIGN THINKING', '["IT","Биотех","Art & Design","Спорт","Предпринимательство"]'::jsonb, 'Дети — стажёры «Института Прикладного Будущего». Каждый день они работают в новой лаборатории: Робототехника, Программирование, Экотехнологии, Дизайн или Медицина. В финале — объединяются в команды и запускают собственный стартап.', 'За каждую пройденную лабораторию дети получают «Профессиональную лицензию» и «Крипто-кредиты». Каждый день — «Хакатон-час». Финал — Demo Day с презентацией проектов.', 'Институт работает как международная организация: все инструкции, чертежи и презентации — на английском. Вожатые выступают в роли «научных супервайзеров».', '«Лабораторная разминка» с Blazepod и балансбордами, «инженерная эстафета» и «программистская йога».', 'Робо-инженер, IoT-разработчик, биотехнолог, UX/UI-дизайнер.', 'Прототип «Умного устройства для дома» на Arduino. Стартап-команды с ролями, интервью с пользователями, финальный Demo Day.', '[{"name":"IT","icon":"💻","missions":[{"name":"Лаборатория Робототехники","desc":"Сборка и программирование роботов на Arduino","skills":["problem_solving","creativity"],"professions":["Робо-инженер","Мехатроник"],"futureSkills":["Программирование Arduino","Сборка роботов"]},{"name":"Лаборатория Программирования","desc":"Создание приложений и игр на Scratch/Python","skills":["problem_solving","learning_ability"],"professions":["Разработчик ПО","Гейм-разработчик"],"futureSkills":["Python и Scratch","Разработка приложений"]},{"name":"IoT: умное устройство","desc":"Проектирование.connected-устройства для дома","skills":["critical_thinking","problem_solving"],"professions":["IoT-разработчик","Инженер умного дома"],"futureSkills":["Интернет вещей","Подключение датчиков"]},{"name":"Хакатон-час","desc":"Быстрое решение практической задачи за ограниченное время","skills":["adaptability","initiative"],"professions":["Продуктовый инженер","Тимлид разработки"],"futureSkills":["Быстрое прототипирование","Работа под дедлайном"]}]},{"name":"Биотех","icon":"🧬","missions":[{"name":"Лаборатория Экотехнологий","desc":"Изучение возобновляемых источников энергии","skills":["curiosity","critical_thinking"],"professions":["Эко-инженер","Специалист GreenTech"],"futureSkills":["Возобновляемая энергетика","Экологический дизайн"]},{"name":"Лаборатория Медицины","desc":"Основы биометрии и измерения параметров тела","skills":["curiosity","learning_ability"],"professions":["Врач цифровой медицины","Биоинженер медицинских устройств"],"futureSkills":["Биометрия","Основы физиологии человека"]},{"name":"Биоинженерные решения","desc":"Проектирование экологичных систем для жизни","skills":["creativity","problem_solving"],"professions":["Биотехнолог","Инженер бионических систем"],"futureSkills":["Биомиметика","Проектирование экосистем"]}]},{"name":"Art & Design","icon":"🎨","missions":[{"name":"Лаборатория Дизайна","desc":"UX/UI-проектирование интерфейсов устройств","skills":["creativity","critical_thinking"],"professions":["UX/UI-дизайнер","Продуктовый дизайнер"],"futureSkills":["Проектирование интерфейсов","Пользовательские сценарии"]},{"name":"Концепт-арт продукта","desc":"Визуализация идеи перед началом разработки","skills":["creativity","communication"],"professions":["Концепт-художник","Промышленный дизайнер"],"futureSkills":["Цифровой рисунок","Визуализация идей"]},{"name":"Прототипирование","desc":"Быстрое создание физической модели решения","skills":["creativity","self_organization"],"professions":["Прототипист","Maker-инженер"],"futureSkills":["Быстрые макеты","3D-печать"]}]},{"name":"Спорт","icon":"🏅","missions":[{"name":"Лабораторная разминка","desc":"Активные паузы с Blazepod и балансбордами","skills":["adaptability","persistence"],"professions":["Тренер по фитнесу","Спортивный аналитик"],"futureSkills":["Разминка с LED-тренажёрами","Баланс-тренировки"]},{"name":"Инженерная эстафета","desc":"Командное соревнование с инженерными задачами","skills":["cooperation","initiative"],"professions":["Тимлид инженерной команды","Организатор технических соревнований"],"futureSkills":["Командное решение задач","Скоростная сборка конструкций"]},{"name":"Программистская йога","desc":"Растяжка и релаксация между блоками работы","skills":["self_organization","persistence"],"professions":["Wellness-специалист","Тренер по восстановлению"],"futureSkills":["Осознанность и концентрация","Профилактика выгорания"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Стартап-команды","desc":"Формирование команд с распределением ролей","skills":["initiative","cooperation"],"professions":["Сооснователь стартапа","Продакт-менеджер"],"futureSkills":["Роли в стартап-команде","Team building"]},{"name":"Интервью с пользователями","desc":"Исследование потребностей для улучшения продукта","skills":["communication","curiosity"],"professions":["UX-исследователь","CustDev-аналитик"],"futureSkills":["Customer Development","Анализ потребностей аудитории"]},{"name":"Demo Day","desc":"Финальная презентация проектов перед «инвестиционным комитетом»","skills":["communication","social_position"],"professions":["CEO стартапа","Питч-продюсер"],"futureSkills":["Публичный питч","Демонстрация продукта"]}]}]'::jsonb),
(5, 'Bio-points', '«Active Tech 2077: Академия Био-Тех Спорта»', 'SPORTS TECH & BIOHACKING', '["Спорт","Биотех","IT","Предпринимательство"]'::jsonb, 'Спортивная академия 2077 года. Каждый ребёнок — «атлет-биоапгрейдер», который прокачивает четыре характеристики — Силу, Скорость, Выносливость и Технику — и готовится к «Цифровым Олимпийским Играм».', 'У каждого участника — «Цифровой паспорт атлета» с личными показателями. В течение смены дети собирают «персональный имплант» и соревнуются в турнирной таблице.', 'Тренировки, брифинги, инструкции по сборке и разбор данных — всё на английском. Тренеры играют роль «коучей из разных стран».', 'Техно-футбол с GPS-трекерами, лёгкая атлетика с биометрическими браслетами, кибер-йога, AR-ориентирование и техно-фрисби.', 'Спортивный аналитик, инженер носимых устройств и тренер по биохакингу.', 'Спортивный трекер на Arduino или micro:bit. Персональная тренировочная программа на основе собранных данных. Защита на «Спортивном саммите».', '[{"name":"Спорт","icon":"🏅","missions":[{"name":"Техно-футбол с GPS","desc":"Игра с отслеживанием перемещений через GPS-трекеры","skills":["cooperation","adaptability"],"professions":["Спортивный аналитик","Тренер по футболу"],"futureSkills":["GPS-трекинг в спорте","Анализ игровых данных"]},{"name":"Лёгкая атлетика с биометрией","desc":"Бег и прыжки с анализом через биометрические браслеты","skills":["persistence","critical_thinking"],"professions":["Биомеханик","Тренер по лёгкой атлетике"],"futureSkills":["Работа с биометрическими браслетами","Техника бега и прыжков"]},{"name":"Кибер-йога","desc":"Йога с элементами геймификации и датчиками","skills":["self_organization","adaptability"],"professions":["Инструктор йоги","Специалист по digital-wellness"],"futureSkills":["Геймифицированные практики","Телесная осознанность"]},{"name":"AR-ориентирование","desc":"Поиск точек по augmented reality карте","skills":["problem_solving","adaptability"],"professions":["Разработчик AR-приложений","Инструктор по спортивной навигации"],"futureSkills":["Навигация в augmented reality","Работа с AR-картами"]},{"name":"Техно-фрисби","desc":"Фрисби с электронными метками для подсчёта очков","skills":["cooperation","initiative"],"professions":["Организатор спортивных событий","Тренер по фрисби"],"futureSkills":["Электронный подсчёт очков","Командные игры с гаджетами"]}]},{"name":"Биотех","icon":"🧬","missions":[{"name":"Биометрия атлета","desc":"Измерение пульса, SpO2, уровня стресса до и после нагрузки","skills":["curiosity","critical_thinking"],"professions":["Биохакер","Спортивный врач"],"futureSkills":["Измерение пульса и SpO2","Оценка уровня стресса"]},{"name":"Персональный имплант","desc":"Сборка носимого устройства для мониторинга здоровья","skills":["problem_solving","creativity"],"professions":["Инженер носимых устройств","Биомедицинский инженер"],"futureSkills":["Сборка wearables","Мониторинг показателей здоровья"]},{"name":"Биохакинг: восстановление","desc":"Изучение методов восстановления после тренировок","skills":["learning_ability","self_organization"],"professions":["Тренер по биохакингу","Реабилитолог"],"futureSkills":["Протоколы восстановления","Управление сном и регенерацией"]}]},{"name":"IT","icon":"💻","missions":[{"name":"Цифровой паспорт атлета","desc":"Создание личного профиля с показателями в приложении","skills":["self_organization","learning_ability"],"professions":["Разработчик приложений","UX/UI-дизайнер"],"futureSkills":["Создание цифровых профилей","Работа с мобильными приложениями"]},{"name":"Сборка трекера на Arduino","desc":"Программирование и настройка спортивного трекера","skills":["problem_solving","persistence"],"professions":["Hardware-инженер","IoT-разработчик"],"futureSkills":["Программирование Arduino","Датчики движения и пульса"]},{"name":"Анализ спортивных данных","desc":"Обработка и визуализация данных тренировок","skills":["critical_thinking","learning_ability"],"professions":["Sports Data Analyst","Data Scientist"],"futureSkills":["Визуализация тренировочных данных","Статистика в спорте"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Турнирная таблица","desc":"Соревнование между участниками на основе баллов","skills":["critical_thinking","initiative"],"professions":["Организатор турниров","Спортивный менеджер"],"futureSkills":["Рейтинговые системы","Соревновательная аналитика"]},{"name":"Персональная программа","desc":"Создание индивидуального плана тренировок на основе данных","skills":["self_organization","critical_thinking"],"professions":["Персональный тренер","Составитель тренировочных программ"],"futureSkills":["Индивидуальные тренировочные планы","Data-driven подход к тренировкам"]},{"name":"Защита на Спортивном саммите","desc":"Презентация результатов и персонального трекера","skills":["communication","social_position"],"professions":["Спортивный спикер","Презентатор продуктов"],"futureSkills":["Публичная защита проекта","Презентация результатов"]}]}]'::jsonb),
(6, 'Ключи к Городскому Разуму', '«Urban Quest: Агенты Городского Разума»', 'CITY ADVENTURE & AR', '["IT","Медиа","Спорт","Art & Design","Предпринимательство"]'::jsonb, 'Городской ИИ вышел из-под контроля, и только дети-агенты «Городского Разума» могут его остановить. Каждый день — новая зона города, новая миссия и новые улики.', 'Дети работают через квест-приложение или Telegram-бот с картой города. По всему кампусу расставлены AR-метки и QR-коды. За выполнение миссий — «Ключи к Городскому Разуму». Финал — «Взлом Центрального Ядра».', 'Все задания, шифры и переговоры с «информаторами» — на английском. У каждого агента — кодовое имя и ежедневные брифинги на английском.', 'Паркур-разведка по территории, ориентирование с QR/AR-метками, командные эстафеты «Спасение заложника» и «Передача данных», доджбол-штурм.', 'Квест-дизайнер, специалист по кибербезопасности, аналитик геоданных и медиажурналист.', 'Мини-квест с QR/AR для родителей и промо-ролик на английском. Данные о районе (шум, маршруты, воздух) лежат в основе продукта.', '[{"name":"IT","icon":"💻","missions":[{"name":"QR/AR-квест по карте","desc":"Прохождение миссий через сканирование QR-кодов и AR-меток","skills":["problem_solving","curiosity"],"professions":["Квест-дизайнер","AR-разработчик"],"futureSkills":["Сканирование QR/AR-меток","Навигация по цифровой карте"]},{"name":"Telegram-бот навигатор","desc":"Использование бота для получения заданий и координат","skills":["learning_ability","problem_solving"],"professions":["Разработчик чат-ботов","Product-менеджер мессенджеров"],"futureSkills":["Работа с Telegram-ботами","Автоматизация задач"]},{"name":"Кибербезопасность: взлом ядра","desc":"Финальная миссия по восстановлению контроля над ИИ","skills":["critical_thinking","persistence"],"professions":["Специалист по кибербезопасности","Этичный хакер"],"futureSkills":["Основы информационной безопасности","Логика защиты систем"]},{"name":"Анализ геоданных","desc":"Сбор и обработка данных о городе (шум, маршруты, воздух)","skills":["critical_thinking","learning_ability"],"professions":["Аналитик геоданных","Urban Data Scientist"],"futureSkills":["Сбор городских данных","Картографический анализ"]}]},{"name":"Медиа","icon":"🎬","missions":[{"name":"Промо-ролик квеста","desc":"Съёмка трейлера мини-квеста на английском","skills":["creativity","communication"],"professions":["Видеопродюсер","Маркетолог"],"futureSkills":["Съёмка трейлеров","Промо-стратегии"]},{"name":"Оперативные донесения","desc":"Ведение видеодневника агента с ежедневными отчётами","skills":["communication","self_organization"],"professions":["Медиажурналист","SMM-специалист"],"futureSkills":["Ведение видеодневника","Регулярный выпуск контента"]},{"name":"Медиажурналистика","desc":"Интервью с «информаторами» и создание репортажей","skills":["communication","curiosity"],"professions":["Репортёр","Интервьюер"],"futureSkills":["Уличные интервью","Репортаж на английском"]}]},{"name":"Спорт","icon":"🏅","missions":[{"name":"Паркур-разведка","desc":"Преодоление препятствий на территории кампуса","skills":["adaptability","persistence"],"professions":["Трейсер","Инструктор по паркуру"],"futureSkills":["Безопасное преодоление препятствий","Городская навигация"]},{"name":"Эстафета «Спасение заложника»","desc":"Командная миссия на скорость и ловкость","skills":["cooperation","initiative"],"professions":["Спасатель","Инструктор тактической подготовки"],"futureSkills":["Командные операции","Скоростная координация"]},{"name":"Доджбол-штурм","desc":"Тактическая игра для захвата контрольной точки","skills":["adaptability","cooperation"],"professions":["Тренер по командным видам спорта","Организатор турниров"],"futureSkills":["Тактическое мышление","Контроль территории"]},{"name":"Ориентирование с AR","desc":"Поиск скрытых объектов по augmented reality подсказкам","skills":["problem_solving","curiosity"],"professions":["Дизайнер городских игр","Инструктор по навигации"],"futureSkills":["AR-навигация","Поиск скрытых объектов"]}]},{"name":"Art & Design","icon":"🎨","missions":[{"name":"Дизайн QR-точек","desc":"Создание визуального оформления для QR-квеста","skills":["creativity","self_organization"],"professions":["Графический дизайнер","Дизайнер городской навигации"],"futureSkills":["Визуальная айдентика","Дизайн QR-локаций"]},{"name":"Карта города","desc":"Проектирование интерактивной карты с зонами миссий","skills":["creativity","critical_thinking"],"professions":["Картограф","Урбанист"],"futureSkills":["Интерактивные карты","Проектирование городских зон"]},{"name":"Айдентика агента","desc":"Разработка кодового имени и визуального стиля персонажа","skills":["creativity","communication"],"professions":["Бренд-дизайнер","Гейм-дизайнер персонажей"],"futureSkills":["Разработка персонажа","Создание визуального стиля"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Мини-квест для родителей","desc":"Создание коммерческого продукта — квеста для внешней аудитории","skills":["initiative","creativity"],"professions":["Продюсер квестов","Event-предприниматель"],"futureSkills":["Создание продукта для аудитории","Коммерциализация игр"]},{"name":"Защита «Ключей к Городскому Разуму»","desc":"Презентация накопленных данных и решений","skills":["communication","social_position"],"professions":["Презентатор","Проджект-менеджер"],"futureSkills":["Защита накопленных результатов","Публичный отчёт"]},{"name":"Юнит-экономика квеста","desc":"Расчёт стоимости создания и монетизации квест-продукта","skills":["critical_thinking","problem_solving"],"professions":["Продуктовый аналитик","Экономист проекта"],"futureSkills":["Расчёт себестоимости","Модели монетизации"]}]}]'::jsonb),
(7, 'Мега-ватты', '«Smart City Lab: Архитекторы Умного Города»', 'URBAN TECH & LOGISTICS', '["IT","Art & Design","Биотех","Спорт","Дипломатия"]'::jsonb, 'Мегаполис будущего перешёл на ручное управление из-за сбоя в центральном ИИ. Дети — элитный отряд «Сити-архитекторов». Их задача — за 5 дней пересобрать инфраструктуру одного квартала.', 'Кампус — это сетка умного города. Команды зарабатывают «Мега-ватты» через спорт и решение логистических кейсов. У каждого ребёнка — роль: Логист, Эко-инженер или Сетевик. В финале все системы активируются одновременно.', 'Язык проектной документации и градостроительства. Дети учат урбанистическую терминологию, проводят «брифинги с мэрией» на английском и защищают чертежи перед «Инвестиционным фондом города».', '«Доставка грузов» (полоса препятствий), пилотирование мини-дронов, «Светофор» (Blazepod), паркур-доставка.', 'Урбанист, логистический аналитик, инженер умных сетей, специалист по городской экологии.', 'Физический макет «Умного квартала» с работающими элементами на micro:bit: автоматические шлагбаумы, умное освещение, мониторинг качества воздуха.', '[{"name":"IT","icon":"💻","missions":[{"name":"Программирование на micro:bit","desc":"Создание работающих элементов: шлагбаумы, освещение, датчики","skills":["problem_solving","learning_ability"],"professions":["IoT-разработчик","Инженер умных сетей"],"futureSkills":["Работа с микроконтроллерами","Автоматизация инфраструктуры"]},{"name":"Система мониторинга воздуха","desc":"Сборка датчика качества воздуха и визуализация данных","skills":["critical_thinking","curiosity"],"professions":["Эколог-аналитик","Инженер сенсорных систем"],"futureSkills":["Датчики качества воздуха","Экологический мониторинг"]},{"name":"Логистические кейсы","desc":"Оптимизация маршрутов и распределения ресурсов в городе","skills":["critical_thinking","problem_solving"],"professions":["Логистический аналитик","Специалист по цепочкам поставок"],"futureSkills":["Оптимизация маршрутов","Управление ресурсами города"]},{"name":"Сетевая инфраструктура","desc":"Проектирование связи между объектами умного квартала","skills":["problem_solving","self_organization"],"professions":["Сетевой инженер","Архитектор телеком-систем"],"futureSkills":["Проектирование сетей связи","Интеграция urban-объектов"]}]},{"name":"Art & Design","icon":"🎨","missions":[{"name":"Физический макет квартала","desc":"Сборка масштабной модели умного городского квартала","skills":["creativity","cooperation"],"professions":["Урбанист","Архитектор"],"futureSkills":["Макетирование","Планирование городских кварталов"]},{"name":"Проектирование чертежей","desc":"Создание планов инфраструктуры и инженерных систем","skills":["self_organization","critical_thinking"],"professions":["Инженер-проектировщик","BIM-модельер"],"futureSkills":["Чтение и создание чертежей","Инженерные системы зданий"]},{"name":"Визуализация данных","desc":"Оформление результатов мониторинга в наглядном виде","skills":["creativity","critical_thinking"],"professions":["Data-визуализатор","Дизайнер инфографики"],"futureSkills":["Инфографика","Дашборды данных"]}]},{"name":"Биотех","icon":"🧬","missions":[{"name":"Эко-инженерия","desc":"Проектирование систем очистки воздуха и воды","skills":["problem_solving","social_position"],"professions":["Эко-инженер","Специалист по очистным технологиям"],"futureSkills":["Очистка воздуха и воды","Зелёные технологии"]},{"name":"Мониторинг окружающей среды","desc":"Сбор данных о качестве воздуха, шуме, температуре","skills":["curiosity","persistence"],"professions":["Эколог города","Климатолог"],"futureSkills":["Замеры шума и температуры","Экологические отчёты"]},{"name":"Устойчивые решения","desc":"Интеграция экологичных технологий в городскую среду","skills":["critical_thinking","social_position"],"professions":["Специалист устойчивого развития","Инженер Green Building"],"futureSkills":["Устойчивая урбанистика","Энергоэффективность зданий"]}]},{"name":"Спорт","icon":"🏅","missions":[{"name":"Доставка грузов","desc":"Полоса препятствий с переносом модулей инфраструктуры","skills":["persistence","cooperation"],"professions":["Логист","Тренер по функциональной подготовке"],"futureSkills":["Логистические операции","Переноска и упаковка грузов"]},{"name":"Пилотирование мини-дронов","desc":"Управление дронами для облёта территории","skills":["adaptability","problem_solving"],"professions":["Оператор дронов","Инженер БПЛА"],"futureSkills":["Управление дронами","Аэросъёмка территории"]},{"name":"Светофор на Blazepod","desc":"Тренировка реакции в формате городской игры","skills":["adaptability","persistence"],"professions":["Тренер по реакции","Спортивный аналитик"],"futureSkills":["Работа с LED-тренажёрами","Скорость реакции"]},{"name":"Паркур-доставка","desc":"Быстрая доставка компонентов через препятствия","skills":["initiative","adaptability"],"professions":["Трейсер","Курьер нового поколения"],"futureSkills":["Быстрая доставка","Городская навигация"]}]},{"name":"Дипломатия","icon":"🤝","missions":[{"name":"Брифинги с мэрией","desc":"Презентация проектов «Инвестиционному фонду города» на английском","skills":["communication","social_position"],"professions":["Урбанист-консультант","Специалист по связям с общественностью"],"futureSkills":["Презентации для органов власти","Урбанистическая терминология на английском"]},{"name":"Межкомандная координация","desc":"Распределение зон ответственности между архитекторами","skills":["cooperation","self_organization"],"professions":["Координатор проектов","Менеджер мегапроектов"],"futureSkills":["Распределение зон ответственности","Кросс-командное взаимодействие"]},{"name":"Защита чертежей","desc":"Публичная презентация urban-проекта перед жюри","skills":["communication","critical_thinking"],"professions":["Архитектор","Инженер-презентатор"],"futureSkills":["Защита проектной документации","Публичные презентации"]}]}]'::jsonb),
(8, 'Studio Coins', '«ENGLISH GAME STUDIO: Код Доступа»', 'GAMEDEV & DIGITAL PRODUCT', '["IT","Art & Design","Медиа","Предпринимательство","Спорт"]'::jsonb, 'Дети — сотрудники инди-студии «Pixel Forge». Им поступил заказ от международного издателя: за неделю создать играбельный прототип 3D-игры, пройти фокус-группы и подготовить релиз.', 'Студия работает по методологии Agile. Утро начинается со «Stand-up» планёрки. За закрытие спринтов команды получают «Бейджи фич». Внутренняя валюта «Studio Coins» тратится на аукционе редкого игрового инвентаря.', '100% рабочий процесс студии — на английском. Брифинги, написание лора, код-ревью, маркетинговые питчи и общение с «зарубежными издателями» — строго на английском.', '«Битва с боссом» (физические челленджи на время), VR/AR-активности, танцевальные баттлы (Just Dance), эстафеты «Сбор апгрейдов».', 'Гейм-дизайнер, 3D-моделлер, QA-тестировщик, нарративный дизайнер, комьюнити-менеджер.', 'Играбельный билд игры (Roblox Studio или Scratch 3D) + физический мерч: кастомный геймпад из картона и электроники или 3D-печатные брелоки.', '[{"name":"IT","icon":"💻","missions":[{"name":"Разработка в Roblox/Scratch","desc":"Создание играбельного прототипа 3D-игры","skills":["problem_solving","creativity"],"professions":["Гейм-разработчик","Программист игровых движков"],"futureSkills":["Разработка 3D-игр","Скриптинг игровой логики"]},{"name":"Код-ревью","desc":"Проверка и оптимизация кода коллег по команде","skills":["critical_thinking","communication"],"professions":["Senior-разработчик","Tech Lead"],"futureSkills":["Чтение чужого кода","Конструктивная обратная связь"]},{"name":"Stand-up планёрка","desc":"Ежедневная синхронизация команды по методологии Agile","skills":["communication","self_organization"],"professions":["Scrum-мастер","Project Manager"],"futureSkills":["Agile-методологии","Ежедневные синхронизации команды"]},{"name":"QA-тестирование","desc":"Поиск багов и тестирование геймплея","skills":["critical_thinking","persistence"],"professions":["QA-тестировщик","Game QA Engineer"],"futureSkills":["Поиск и описание багов","Составление тест-кейсов"]}]},{"name":"Art & Design","icon":"🎨","missions":[{"name":"3D-моделлинг","desc":"Создание персонажей, окружения и объектов для игры","skills":["creativity","self_organization"],"professions":["3D-моделлер","Гейм-артист"],"futureSkills":["3D-графика","Создание игровых ассетов"]},{"name":"Кастомный геймпад","desc":"Проектирование и сборка физического контроллера из картона и электроники","skills":["creativity","problem_solving"],"professions":["Промышленный дизайнер","Hardware-мейкер"],"futureSkills":["Прототипирование контроллеров","Мягкая электроника"]},{"name":"Дизайн интерфейса","desc":"Разработка UI/UX внутриигрового интерфейса","skills":["creativity","critical_thinking"],"professions":["UI/UX-дизайнер игр","Дизайн-инженер интерфейсов"],"futureSkills":["Игровой UI/UX","Дизайн-системы"]},{"name":"3D-печать брелоков","desc":"Создание физических мерч-продуктов с героями игры","skills":["creativity","persistence"],"professions":["3D-моделлер мерча","Оператор 3D-печати"],"futureSkills":["Подготовка моделей к печати","Производство мерча"]}]},{"name":"Медиа","icon":"🎬","missions":[{"name":"Написание лора","desc":"Создание истории мира и персонажей на английском","skills":["creativity","communication"],"professions":["Нарративный дизайнер","Геймрайтер"],"futureSkills":["Мировостроение","Сторителлинг на английском"]},{"name":"Маркетинговый питч","desc":"Презентация игры «издателям» (вожатым) на английском","skills":["communication","initiative"],"professions":["Игровой маркетолог","Продюсер издателя"],"futureSkills":["Питчинг издателям","Маркетинг игр"]},{"name":"Промо-ролик игры","desc":"Съёмка трейлера для продвижения продукта","skills":["creativity","communication"],"professions":["Трейлермейкер","Видеопродюсер"],"futureSkills":["Съёмка гейм-трейлеров","Монтаж промо-материалов"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Юнит-экономика игры","desc":"Расчёт стоимости создания и потенциальной прибыли","skills":["critical_thinking","problem_solving"],"professions":["Продуктовый экономист","Аналитик монетизации"],"futureSkills":["Экономика игровых проектов","Расчёт LTV и CAC"]},{"name":"Studio Coins: внутренняя валюта","desc":"Управление бюджетом студии и аукцион инвентаря","skills":["self_organization","critical_thinking"],"professions":["Гейм-экономист","Управляющий студией"],"futureSkills":["Внутриигровые валюты","Управление бюджетом"]},{"name":"Фокус-группы","desc":"Тестирование игры с реальными пользователями и сбор фидбека","skills":["communication","curiosity"],"professions":["UX-исследователь","Community Manager"],"futureSkills":["Сбор пользовательского фидбека","Модерация тестирований"]},{"name":"Релиз и Demo Day","desc":"Финальная презентация игры родителям в зоне с ноутбуками","skills":["communication","social_position"],"professions":["Продюсер релиза","Гейм-предприниматель"],"futureSkills":["Релизный цикл продукта","Публичная демонстрация игры"]}]},{"name":"Спорт","icon":"🏅","missions":[{"name":"Битва с боссом","desc":"Физические челленджи на время как элемент геймплея","skills":["persistence","initiative"],"professions":["Тренер по функциональной подготовке","Дизайнер физических челленджей"],"futureSkills":["Челленджи на время","Геймификация фитнеса"]},{"name":"VR/AR-активности","desc":"Игры в виртуальной и дополненной реальности","skills":["adaptability","curiosity"],"professions":["VR-оператор","Разработчик VR-игр"],"futureSkills":["Навигация в VR","Иммерсивные игровые механики"]},{"name":"Танцевальные баттлы","desc":"Just Dance и другие ритм-игры для разминки","skills":["creativity","adaptability"],"professions":["Хореограф","Ведущий танцевальных шоу"],"futureSkills":["Ритм-координация","Сценическая подача"]},{"name":"Эстафета «Сбор апгрейдов»","desc":"Командное соревнование на скорость и точность","skills":["cooperation","persistence"],"professions":["Организатор киберспортивных мероприятий","Тренер команд"],"futureSkills":["Командная скорость","Точность выполнения заданий"]}]}]'::jsonb),
(9, 'Bio-points', '«CHAMPIONS ACADEMY: Био-Механика Побед»', 'SPORTS TECH & DATA ANALYTICS', '["Спорт","Дипломатия","Предпринимательство"]'::jsonb, 'Это не просто спорт — это лаборатория человеческих возможностей. Дети — «атлеты-исследователи» в Академии спорта будущего. Они оцифровывают свои показатели, ищут слабые места в биомеханике и с помощью технологий выходят на новый уровень.', 'У каждого ребёнка — «Биометрический паспорт». За победы начисляются «Bio-points». Дети соревнуются не только друг с другом, но и со своими вчерашними показателями — личный рекорд важнее места в таблице.', 'Язык спортивной аналитики и медицины. Дети учат анатомию и терминологию фитнеса, дают спортивные комментарии и проводят интервью с «чемпионами» на английском.', 'Спорт с гаджетами: бег с GPS-трекерами и анализом пульса, тренировки реакции на Blazepod, балансборды, нейрогимнастика, фехтование на мягких мечах с датчиками.', 'Спортивный аналитик, биохакер, инженер спортивного инвентаря, реабилитолог.', 'Персональный «Атлетический дашборд» (отчёт с графиками прогресса) + собранный тренажёр: реакционная лестница с электронными датчиками или баланс-платформа.', '[{"name":"Спорт","icon":"🏅","missions":[{"name":"Бег с GPS-трекерами","desc":"Анализ пульса и маршрута в реальном времени","skills":["persistence","critical_thinking"],"professions":["Спортивный аналитик","Тренер по лёгкой атлетике"],"futureSkills":["GPS-анализ бега","Мониторинг пульса в реальном времени"]},{"name":"Тренировки на Blazepod","desc":"Развитие реакции с LED-тренажёрами","skills":["adaptability","persistence"],"professions":["Тренер по биохакингу","Спортивный аналитик"],"futureSkills":["Работа с LED-тренажёрами","Скорость реакции"]},{"name":"Балансборды","desc":"Укрепление кора и координации на нестабильных платформах","skills":["persistence","self_organization"],"professions":["Тренер по функциональной подготовке","Реабилитолог"],"futureSkills":["Тренировка баланса","Укрепление кора"]},{"name":"Нейрогимнастика","desc":"Координационные упражнения для связи мозга и тела","skills":["curiosity","adaptability"],"professions":["Нейротренер","Специалист по когнитивному фитнесу"],"futureSkills":["Мозго-телесные связи","Координационные паттерны"]},{"name":"Фехтование с датчиками","desc":"Бой на мягких мечах с электронным подсчётом попаданий","skills":["initiative","critical_thinking"],"professions":["Фехтовальщик","Инженер спортивного инвентаря"],"futureSkills":["Электронный подсчёт попаданий","Тактика боя"]}]},{"name":"Дипломатия","icon":"🤝","missions":[{"name":"Спортивные комментарии","desc":"Ведение трансляции соревнований на английском","skills":["communication","creativity"],"professions":["Спортивный комментатор","Стример"],"futureSkills":["Live-комментирование на английском","Работа с микрофоном"]},{"name":"Интервью с чемпионами","desc":"Проведение интервью с участниками после соревнований","skills":["communication","curiosity"],"professions":["Спортивный журналист","Интервьюер"],"futureSkills":["Послематчевые интервью","Вопросы на английском"]},{"name":"Анатомия на английском","desc":"Изучение терминологии фитнеса и спортивной медицины","skills":["learning_ability","curiosity"],"professions":["Спортивный врач","Физиолог"],"futureSkills":["Спортивная терминология","Основы анатомии"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Биометрический паспорт","desc":"Создание личного профиля атлета с показателями","skills":["self_organization","learning_ability"],"professions":["Биохакер","Разработчик спортивных приложений"],"futureSkills":["Цифровые профили атлета","Работа с биометрией"]},{"name":"Атлетический дашборд","desc":"Анализ графиков прогресса за смену","skills":["critical_thinking","problem_solving"],"professions":["Sports Data Analyst","BI-аналитик"],"futureSkills":["Построение графиков прогресса","Анализ динамики показателей"]},{"name":"Защита на Спортивном саммите","desc":"Презентация результатов и личного прогресса перед жюри","skills":["communication","social_position"],"professions":["Спортивный менеджер","Презентатор"],"futureSkills":["Защита личного прогресса","Публичное выступление"]},{"name":"Bio-points: система баллов","desc":"Управление личными достижениями и рейтингом","skills":["self_organization","critical_thinking"],"professions":["Организатор рейтингов","Гейм-дизайнер мотивационных систем"],"futureSkills":["Системы достижений","Самоконтроль прогресса"]}]}]'::jsonb),
(10, 'Литры пресной воды', '«ISLAND SURVIVAL: Eco-Tech Экспедиция»', 'SURVIVAL TECH & ECO-ENGINEERING', '["Спорт","Дипломатия","Предпринимательство"]'::jsonb, 'Команды «исследователей» терпят «крушение» на необитаемом острове. Но у них есть не просто палатки, а «Техно-десант» — набор гаджетов и материалов. Задача — построить высокотехнологичный эко-отдых.', 'Команды получают «Техно-дропы» (детали для проектов) за прохождение физических испытаний в «Диких зонах». Внутренняя валюта — «Литры пресной воды», которые нужно зарабатывать и экономить.', 'Язык выживания и координации. Дети учатся передавать координаты, описывать биологические виды, вести «Бортовой журнал» и вести переговоры об обмене ресурсами — исключительно на английском.', 'Спортивное ориентирование с компасами и GPS, верёвочный курс «Переправа», строительство плотов или носилок, слэклайн, эстафеты «Эвакуация раненого».', 'Инженер по выживанию, эко-технолог, специалист по альтернативной энергетике, координатор спасательных операций.', 'Работающая «Станция выживания»: ветрогенератор, заряжающий powerbank и питающий LED-маяк, или система фильтрации воды с датчиком мутности на Arduino.', '[{"name":"Спорт","icon":"🏅","missions":[{"name":"Ориентирование с GPS","desc":"Поиск точек по координатам и компасу на территории","skills":["problem_solving","adaptability"],"professions":["Штурман","Инструктор по ориентированию"],"futureSkills":["Работа с компасом и GPS","Чтение координат"]},{"name":"Верёвочный курс «Переправа»","desc":"Преодоление водной преграды с помощью верёвок","skills":["cooperation","persistence"],"professions":["Инструктор верёвочного парка","Спасатель"],"futureSkills":["Навесные переправы","Страховочные узлы"]},{"name":"Строительство плотов","desc":"Конструирование плавсредств из подручных материалов","skills":["creativity","problem_solving"],"professions":["Инженер по выживанию","Специалист по плавсредствам"],"futureSkills":["Конструирование плотов","Работа с подручными материалами"]},{"name":"Слэклайн","desc":"Балансировка на натянутой ленте для координации","skills":["persistence","adaptability"],"professions":["Инструктор по слэклайну","Тренер по балансу"],"futureSkills":["Балансировка на слэклайне","Концентрация внимания"]},{"name":"Эвакуация раненого","desc":"Эстафета с транспортировкой «пострадавшего» на носилках","skills":["cooperation","initiative"],"professions":["Спасатель","Полевой медик"],"futureSkills":["Транспортировка пострадавших","Первая помощь"]}]},{"name":"Дипломатия","icon":"🤝","missions":[{"name":"Обмен ресурсами","desc":"Переговоры между базами обмена «Литрами пресной воды»","skills":["communication","critical_thinking"],"professions":["Переговорщик","Логист ресурсов"],"futureSkills":["Торговые переговоры на английском","Оценка ценности ресурсов"]},{"name":"Бортовой журнал","desc":"Ведение дневника экспедиции на английском","skills":["self_organization","communication"],"professions":["Документалист экспедиции","Штурман"],"futureSkills":["Ведение журнала на английском","Фиксация маршрутов"]},{"name":"Описание биологических видов","desc":"Классификация и описание найденных растений/животных на английском","skills":["curiosity","learning_ability"],"professions":["Биолог-исследователь","Таксономист"],"futureSkills":["Классификация видов","Научное описание на английском"]},{"name":"Координация спасения","desc":"Планирование и управление спасательной операцией","skills":["initiative","cooperation"],"professions":["Координатор спасательных операций","Руководитель экспедиции"],"futureSkills":["Управление операцией","Распределение ролей в команде"]}]},{"name":"Предпринимательство","icon":"📊","missions":[{"name":"Техно-дропы","desc":"Заработок деталей для проектов через физические испытания","skills":["initiative","persistence"],"professions":["Организатор испытаний","Продюсер соревнований"],"futureSkills":["Заработок через испытания","Управление ресурсными дропами"]},{"name":"Литры пресной воды","desc":"Управление внутренней валютой острова","skills":["self_organization","critical_thinking"],"professions":["Экономист ресурсов","Специалист по водоснабжению"],"futureSkills":["Экономия ресурсов","Бюджетирование"]},{"name":"Защита станции","desc":"Презентация работающей «Станции выживания» родителям","skills":["communication","social_position"],"professions":["Инженер-презентатор","Технологический предприниматель"],"futureSkills":["Демонстрация работающих систем","Публичная защита проекта"]},{"name":"Бизнес-план экоотдыха","desc":"Расчёт ресурсов и планирование инфраструктуры","skills":["critical_thinking","creativity"],"professions":["Основатель эко-курорта","Бизнес-аналитик"],"futureSkills":["Планирование инфраструктуры","Расчёт ресурсов проекта"]}]}]'::jsonb);
